mapper.select:
SELECT t.* ,td.security_type_name AS temp_security_type_name ,fd.security_type_name FROM rrs_temp_fund_code t LEFT JOIN dict_security_type td ON td.security_type = t.temp_security_type AND td.is_deleted = 0 LEFT JOIN dict_security_type fd ON fd.security_type = t.security_type AND fd.is_deleted = 0
AND t.temp_fund_code LIKE CONCAT('%', #{tempFundCode}, '%')
AND t.temp_fund_short_name LIKE CONCAT('%', #{tempFundShortName}, '%')
AND t.status IN #{value}
AND t.oprt_source IN #{value}
ORDER BY CASE t.status WHEN 'temporary' THEN 0 WHEN 'updated' THEN 1 WHEN 'cancelled' THEN 2 ELSE 3 END ,t.update_time DESC ,t.crte_time DESC ,t.id DESC

mapper.update:
UPDATE rrs_temp_fund_code
SET fund_code = #{fundCode}
   ,fund_name = #{fundName}
   ,fund_short_name = #{fundShortName}
   ,market_code = #{marketCode}
   ,security_type = #{securityType}
   ,update_time = #{updateTime}
   ,status = #{status}
   ,is_deleted = #{isDeleted}
   ,oprt_source = #{oprtSource}
   ,updt_time = #{updtTime}
WHERE id = #{id} AND status = 'temporary' AND is_deleted = 0

UPDATE rrs_fundinfo SET security_status = 'D'
                      ,updt_time = #{now}
WHERE fund_code = #{fundCode} AND source_system = 'temporary' AND is_deleted = 0

